-- ============================================================================
-- D3 ASSOCIATE DEEP SEED: Electrofacies, beginner tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/facies/beginner.
--
-- What this tier owns: GROUPING LOGS INTO ELECTROFACIES. Logs as features and
-- a depth sample as a row; the Euclidean distance and why a raw distance is a
-- gamma ray distance; standard scaling with the population standard deviation
-- and min-max scaling without clipping, a constant log refused; principal
-- components from the correlation matrix, their eigenvalues, explained
-- variance, loadings and scores, a new well projected; k-means with seeded
-- k-means++ seeding, Lloyd passes and inertia, several starts; centres back in
-- log units, cluster numbers as names, new rows at the nearest centre;
-- Fisher's iris as a published check. Digest sections 1 to 13, and section 28.
--
-- THE TRAP THE TIER IS BUILT ON. A cluster is a group the logs make, and its
-- number is a name: the scaling decides which rows are near, one start can
-- stop in a poor arrangement, and no cluster is a facies until it is matched
-- against core. The Associate capstone grades six Associate quantities and
-- grades no choice of k, no tree of merges and no score against core.
-- ============================================================================

values ('facies', 'beginner', '{"modules":[{"key":"m01-what-electrofacies-are","title":"What Electrofacies Are","lesson_keys":["l01-logs-as-a-signature-of-rock","l02-core-facies-and-electrofacies","l03-the-ekene-facies-wells","l04-rows-features-and-distance","l05-the-refusals-by-name"]},{"key":"m02-scaling-before-distance","title":"Scaling Before Distance","lesson_keys":["l01-why-gr-rules-a-raw-distance","l02-the-population-standard-deviation","l03-min-max-scaling","l04-a-constant-log"]},{"key":"m03-principal-components","title":"Principal Components","lesson_keys":["l01-the-correlation-matrix","l02-eigenvalues-and-explained-variance","l03-loadings","l04-scores-and-a-new-well"]},{"key":"m04-k-means","title":"k-Means Clustering","lesson_keys":["l01-centres-and-the-nearest-centre","l02-seeding-with-k-means-plus-plus","l03-lloyd-passes","l04-inertia","l05-several-starts"]},{"key":"m05-reading-clusters","title":"Reading Clusters","lesson_keys":["l01-centres-in-log-units","l02-cluster-numbers-are-names","l03-assigning-new-rows","l04-covariance-against-correlation"]},{"key":"m06-one-field-clustered","title":"One Field Clustered, End to End","lesson_keys":["l01-the-whole-workflow","l02-fisher-iris-as-a-check","l03-writing-up-a-clustering","l04-the-capstone-brief"]}]}'::jsonb, 1)
